<?php use App\Core\Auth; ?><section class="panel"><div class="section-heading"><div class="person"><?php if($student['photo_path']): ?><img class="student-photo" src="<?= e(url('image',['id'=>$student['id']])) ?>" alt="Student photo"><?php else: ?><span class="avatar large"><?= e(substr($student['first_name'],0,1)) ?></span><?php endif ?><div><h2><?= e($student['first_name'].' '.$student['middle_name'].' '.$student['last_name']) ?></h2><p><?= e($student['admission_number']) ?> · <?php badge($student['status']); ?></p></div></div><div class="toolbar"><?php if(Auth::can('students.write')): ?><a class="button" href="<?= e(url('student-form',['id'=>$student['id']])) ?>">Edit profile</a><?php endif; if(Auth::can('finance.read')): ?><a class="button primary" href="<?= e(url('statement',['id'=>$student['id']])) ?>">Fee statement →</a><?php endif ?></div></div><div class="detail-grid"><?php foreach(['gender'=>'Gender','date_of_birth'=>'Date of birth','admission_date'=>'Admission date','phone'=>'Phone','email'=>'Email','guardian_name'=>'Guardian','guardian_phone'=>'Guardian phone','address'=>'Address'] as $key=>$label): ?><div><small><?= e($label) ?></small><strong><?= e($student[$key]?:'—') ?></strong></div><?php endforeach ?></div></section>
<section class="panel"><h2>Academic history</h2><p class="muted">Each new enrollment preserves the previous class and financial records.</p><div class="table-wrap"><table><thead><tr><th>Academic year</th><th>Class</th><th>Stream</th><th>Student type</th><th>From</th><th>Status</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= e($h['year_name']) ?></td><td><?= e($h['class_name']) ?></td><td><?= e($h['stream_name']??'—') ?></td><td><?= e($h['type_name']) ?></td><td><?= e($h['starts_on']) ?></td><td><?php badge($h['is_current']?'Active':'Previous'); ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php if(Auth::can('students.write')): ?><details class="panel"><summary>Promote or change enrollment</summary><p class="muted">Select the new enrollment. Existing invoices keep their original academic context.</p><?php startForm('student.enroll',['student_id'=>$student['id']]); enrollmentFields(); endForm('Save new enrollment'); ?></details><details class="panel"><summary>Upload student photo</summary><form method="post" enctype="multipart/form-data" class="stack"><?= csrf() ?><input type="hidden" name="action" value="image.upload"><input type="hidden" name="kind" value="student"><input type="hidden" name="id" value="<?= e($student['id']) ?>"><label>JPEG or PNG · maximum 2 MB<input name="image" type="file" accept="image/jpeg,image/png" required></label><button class="button">Upload photo</button></form></details><?php endif ?>
